1	package log
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"hash/crc32"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"unicode/utf8"
13	)
14	
15	// Named consumer checkpoints live in their own sidecar
16	// ("consumers.idx"), deliberately separate from both the rebuildable
17	// index.idx (pure cache) and truncate.idx (the retention journal). It is
18	// authoritative state, not derived data: deleting index.idx must leave
19	// every consumer's confirmed sequence untouched, and a reopen must
20	// resume exactly the progress that was durable.
21	//
22	// Layout, all integers little-endian:
23	//
24	//	header  8 bytes  "BCLCNM" (6 bytes) + uint16 version
25	//	count   4 bytes  number of registered consumers
26	//	entries count × (8-byte confirmed sequence, 2-byte name length,
27	//	                name bytes)
28	//	crc32   4 bytes  IEEE checksum of every preceding byte
29	//
30	// The whole image is replaced atomically (fsynced temp + rename,
31	// directory synced best effort like the other sidecars), so a crash can
32	// only ever leave the complete previous image or the complete new one —
33	// never a torn or half-applied checkpoint. Unlike index.idx, any defect
34	// (short file, bad magic, an unknown version, a bad checksum, a framing
35	// error or a duplicate name) is fatal: Open returns
36	// ErrCorruptCheckpoint rather than guessing at progress or resetting a
37	// consumer to zero.
38	var (
39		consumersMagic   = []byte{'B', 'C', 'L', 'C', 'N', 'M'}
40		consumersVersion = uint16(1)
41	
42		consumersHeaderLen = 8 + 4
43	)
44	
45	// consumerEntry is one registered consumer's confirmed prefix.
46	type consumerEntry struct {
47		name string
48		seq  uint64
49	}
50	
51	func (l *Log) consumersPath() string {
52		return filepath.Join(l.dir, "consumers.idx")
53	}
54	
55	// validConsumerName reports whether name is an acceptable consumer
56	// name. The rule is the idempotency-key rule — non-empty, valid UTF-8,
57	// NUL-free, at most 256 bytes — but the two namespaces are independent:
58	// a consumer may share a name with an idempotency key.
59	func validConsumerName(name string) bool {
60		if name == "" || len(name) > maxBatchIDLen {
61			return false
62		}
63		if strings.IndexByte(name, 0) >= 0 {
64			return false
65		}
66		return utf8.ValidString(name)
67	}
68	
69	// readConsumers loads and strictly validates consumers.idx. No file (the
70	// common case for a directory written before consumers existed) reports
71	// ok=false with no entries; an old directory simply has no consumers.
72	// Any present-but-defective image is ErrCorruptCheckpoint.
73	func (l *Log) readConsumers() (entries []consumerEntry, ok bool, err error) {
74		data, rerr := os.ReadFile(l.consumersPath())
75		if errors.Is(rerr, os.ErrNotExist) {
76			return nil, false, nil
77		}
78		if rerr != nil {
79			return nil, false, rerr
80		}
81		if len(data) < consumersHeaderLen+4 {
82			return nil, false, ErrCorruptCheckpoint
83		}
84		if string(data[:6]) != string(consumersMagic) {
85			return nil, false, ErrCorruptCheckpoint
86		}
87		if binary.LittleEndian.Uint16(data[6:8]) != consumersVersion {
88			return nil, false, ErrCorruptCheckpoint
89		}
90		stored := binary.LittleEndian.Uint32(data[len(data)-4:])
91		if crc32.ChecksumIEEE(data[:len(data)-4]) != stored {
92			return nil, false, ErrCorruptCheckpoint
93		}
94		count := int(binary.LittleEndian.Uint32(data[8:12]))
95		pos := consumersHeaderLen
96		end := len(data) - 4
97		seen := make(map[string]bool, count)
98		entries = make([]consumerEntry, 0, count)
99		for i := 0; i < count; i++ {
100			if end-pos < 8+2 {
101				return nil, false, ErrCorruptCheckpoint
102			}
103			seq := binary.LittleEndian.Uint64(data[pos : pos+8])
104			pos += 8
105			nlen := int(binary.LittleEndian.Uint16(data[pos : pos+2]))
106			pos += 2
107			if nlen <= 0 || nlen > maxBatchIDLen || end-pos < nlen {
108				return nil, false, ErrCorruptCheckpoint
109			}
110			raw := data[pos : pos+nlen]
111			pos += nlen
112			if strings.IndexByte(string(raw), 0) >= 0 || !utf8.Valid(raw) {
113				return nil, false, ErrCorruptCheckpoint
114			}
115			name := string(raw)
116			if seen[name] {
117				return nil, false, ErrCorruptCheckpoint
118			}
119			seen[name] = true
120			entries = append(entries, consumerEntry{name: name, seq: seq})
121		}
122		if pos != end {
123			// Trailing bytes between the last entry and the checksum: never a
124			// legal image.
125			return nil, false, ErrCorruptCheckpoint
126		}
127		return entries, true, nil
128	}
129	
130	// encodeConsumers serialises the full consumer table in name order with
131	// its trailing checksum.
132	func encodeConsumers(entries []consumerEntry) []byte {
133		sorted := make([]consumerEntry, len(entries))
134		copy(sorted, entries)
135		sort.Slice(sorted, func(i, j int) bool { return sorted[i].name < sorted[j].name })
136		size := consumersHeaderLen + 4
137		for _, e := range sorted {
138			size += 8 + 2 + len(e.name)
139		}
140		buf := make([]byte, 0, size)
141		buf = append(buf, consumersMagic...)
142		var tmp [8]byte
143		binary.LittleEndian.PutUint16(tmp[:2], consumersVersion)
144		buf = append(buf, tmp[:2]...)
145		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(sorted)))
146		buf = append(buf, tmp[:4]...)
147		for _, e := range sorted {
148			binary.LittleEndian.PutUint64(tmp[:], e.seq)
149			buf = append(buf, tmp[:]...)
150			binary.LittleEndian.PutUint16(tmp[:2], uint16(len(e.name)))
151			buf = append(buf, tmp[:2]...)
152			buf = append(buf, e.name...)
153		}
154		binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
155		return append(buf, tmp[:4]...)
156	}
157	
158	// writeConsumers durably replaces consumers.idx with the full table. The
159	// bytes land in a synced temp file before the atomic rename, exactly
160	// like writeTruncateMarker, so a crash leaves one complete image or the
161	// other. Every write is forced through here — checkpoint changes are
162	// durable even when Options.Sync is false.
163	func (l *Log) writeConsumers(entries []consumerEntry) error {
164		path := l.consumersPath()
165		tmp := path + ".tmp"
166		f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
167		if err != nil {
168			return err
169		}
170		if _, err := f.Write(encodeConsumers(entries)); err != nil {
171			f.Close()
172			os.Remove(tmp)
173			return err
174		}
175		if err := syncFile(f); err != nil {
176			f.Close()
177			os.Remove(tmp)
178			return err
179		}
180		if err := f.Close(); err != nil {
181			os.Remove(tmp)
182			return err
183		}
184		if err := os.Rename(tmp, path); err != nil {
185			os.Remove(tmp)
186			return err
187		}
188		_ = syncDir(l.dir)
189		return nil
190	}
191	
192	// consumersList snapshots the registration table as on-disk entries.
193	func (l *Log) consumersList() []consumerEntry {
194		entries := make([]consumerEntry, 0, len(l.consumers))
195		for name, seq := range l.consumers {
196			entries = append(entries, consumerEntry{name: name, seq: seq})
197		}
198		return entries
199	}
200	
201	// AckConsumer confirms consumer name's replay progress through seq and
202	// persists it durably. Consumers Scan from ConsumerSeq(name)+1, process,
203	// and call AckConsumer when the prefix is handled; seq therefore means
204	// "every batch with a sequence up to seq has been processed".
205	//
206	// A name is registered only by its first AckConsumer(name, 0); the
207	// initial confirmed sequence is zero. After that:
208	//
209	//   - seq equal to the stored value succeeds without writing.
210	//   - a greater seq advances the checkpoint; seq must name a committed
211	//     batch (a permanent hole may be skipped over, a group may be
212	//     confirmed as a unit), the batch must not already have been
213	//     reclaimed by DeleteThrough, and no still-staged batch may hold a
214	//     sequence below seq that the prefix claim would overrun.
215	//   - a smaller seq, an unknown/hole/staged/reclaimed target, or a
216	//     staged batch earlier in the sequence space returns ErrInvalidAck
217	//     and changes nothing.
218	//
219	// A syntactically invalid name returns ErrInvalidConsumer. A legal but
220	// unregistered name returns ErrUnknownConsumer (registration is only
221	// AckConsumer(name, 0)). A returned success is durable regardless of
222	// Options.Sync: the target and every earlier committed batch are
223	// fsynced first, then consumers.idx is atomically replaced and synced.
224	// An fsync or metadata write failure returns ErrCheckpointFailed, all
225	// consumer state stays at its previous value and the call retries.
226	func (l *Log) AckConsumer(name string, seq uint64) error {
227		l.mu.Lock()
228		defer l.mu.Unlock()
229		if l.closed {
230			return errClosed
231		}
232		if !validConsumerName(name) {
233			return ErrInvalidConsumer
234		}
235		cur, registered := l.consumers[name]
236		if !registered {
237			if seq != 0 {
238				return ErrUnknownConsumer
239			}
240		} else {
241			switch {
242			case seq == cur:
243				// Confirming the already-confirmed prefix is an idempotent
244				// no-op: no disk write and no extra fsync.
245				return nil
246			case seq < cur:
247				// Checkpoints only move forward.
248				return ErrInvalidAck
249			}
250		}
251		if seq > 0 {
252			if _, committed := l.index[seq]; !committed {
253				// Unknown, a permanent hole, still staged, or already
254				// reclaimed: reclaimed batches leave the index like unknown
255				// ones (and Read distinguishes them as ErrTruncated), but for
256				// a checkpoint every non-committed target is the same
257				// ErrInvalidAck. Note a group that straddled a truncation
258				// boundary can keep a batch with seq <= through readable, so
259				// membership, not through, is the test.
260				return ErrInvalidAck
261			}
