298			// the previous one, and the segment syncs already performed only
299			// made data more durable. Retry freely.
300			return fmt.Errorf("%w: %v", ErrCheckpointFailed, err)
301		}
302		l.consumers[name] = seq
303		return nil
304	}
305	
306	// ConsumerSeq returns consumer name's last confirmed sequence, 0 for a
307	// freshly registered consumer. A syntactically invalid name returns
308	// ErrInvalidConsumer; a legal but unregistered name returns
309	// ErrUnknownConsumer.
310	func (l *Log) ConsumerSeq(name string) (uint64, error) {
311		l.mu.RLock()
312		defer l.mu.RUnlock()
313		if l.closed {
314			return 0, errClosed
315		}
316		if !validConsumerName(name) {
317			return 0, ErrInvalidConsumer
318		}
319		seq, ok := l.consumers[name]
320		if !ok {
321			return 0, ErrUnknownConsumer
322		}
323		return seq, nil
