9	
10	// failingSync turns fsync failures on for the first n segment/sidecar
11	// syncs while it is installed.
12	func installFailingSync(t *testing.T, failAt func(calls int) bool) (calls *int, restore func()) {
13		t.Helper()
14		orig := syncFile
15		n := 0
16		syncFile = func(f *os.File) error {
17			n++
18			if failAt(n) {
19				return errors.New("fsync boom")
20			}
21			return orig(f)
22		}
23		return &n, func() { syncFile = orig }
24	}
25	
26	func TestKeyedSyncFailureKeepsBatchStagedAndDedups(t *testing.T) {
27		dir := t.TempDir()
28		l, err := Open(dir, Options{SegmentBytes: 1 << 20, Sync: true})
29		if err != nil {
30			t.Fatalf("Open: %v", err)
31		}
32		defer l.Close()
33	
34		failing := true
35		orig := syncFile
36		defer func() { syncFile = orig }()
37		syncFile = func(f *os.File) error {
38			if failing {
39				return errors.New("fsync boom")
40			}
41			return orig(f)
42		}
43	
44		b, err := l.AppendIdempotent("k", [][]byte{[]byte("x")})
45		if err != nil {
46			t.Fatalf("AppendIdempotent: %v", err)
47		}
48		if _, err := l.Commit(b); !errors.Is(err, ErrSyncFailed) {
49			t.Fatalf("Commit err = %v, want ErrSyncFailed", err)
50		}
51		// Still staged: the key keeps resolving to the same reserved batch.
52		if _, err := l.Read(1); !errors.Is(err, ErrNotCommitted) {
53			t.Fatalf("Read after failed sync: %v", err)
54		}
55		again, err := l.AppendIdempotent("k", [][]byte{[]byte("x")})
56		if err != nil {
57			t.Fatalf("dedup after failed sync: %v", err)
58		}
59		if again.Seq() != 1 {
60			t.Fatalf("dedup seq = %d, want 1", again.Seq())
61		}
62		if l.fileSize != 0 {
63			t.Fatalf("segment size after failed sync = %d, want 0", l.fileSize)
64		}
65		// Conflicting content still conflicts while staged.
66		if _, err := l.AppendIdempotent("k", [][]byte{[]byte("y")}); !errors.Is(err, ErrBatchIDConflict) {
67			t.Fatalf("conflict after failed sync: %v", err)
68		}
69		// Retry once fsync recovers: exactly one entry.
70		failing = false
71		if seq, err := l.Commit(again); err != nil || seq != 1 {
72			t.Fatalf("retry Commit = %d, %v", seq, err)
73		}
74		got, err := l.Read(1)
75		if err != nil || !reflect.DeepEqual(got, [][]byte{[]byte("x")}) {
76			t.Fatalf("Read(1) = %q, %v", got, err)
77		}
78		l.Close()
79	
80		l2, err := Open(dir, Options{SegmentBytes: 1 << 20, Sync: true})
81		if err != nil {
82			t.Fatalf("reopen: %v", err)
83		}
84		defer l2.Close()
85		count := 0
86		l2.Scan(1, func(Batch) error { count++; return nil })
87		if count != 1 {
88			t.Fatalf("replayed %d batches, want 1 (no duplicate from keyed retry)", count)
89		}
90		if b, err := l2.AppendIdempotent("k", [][]byte{[]byte("x")}); err != nil || b.Seq() != 1 {
91			t.Fatalf("dedup after reopen = %d, %v", b.Seq(), err)
92		}
93	}
94	
95	func TestMixedGroupSyncFailureKeepsAllStaged(t *testing.T) {
96		l, err := Open(t.TempDir(), Options{SegmentBytes: 1 << 20, Sync: true})
97		if err != nil {
98			t.Fatalf("Open: %v", err)
99		}
100		defer l.Close()
101	
102		failing := true
103		orig := syncFile
104		defer func() { syncFile = orig }()
105		syncFile = func(f *os.File) error {
106			if failing {
107				return errors.New("fsync boom")
108			}
109			return orig(f)
110		}
111	
112		a, _ := l.Append([][]byte{[]byte("a")})
113		k, _ := l.AppendIdempotent("gk", [][]byte{[]byte("k")})
114		if _, err := l.CommitGroup([]Batch{a, k}); !errors.Is(err, ErrSyncFailed) {
115			t.Fatalf("CommitGroup err = %v, want ErrSyncFailed", err)
116		}
117		for seq := uint64(1); seq <= 2; seq++ {
118			if _, err := l.Read(seq); !errors.Is(err, ErrNotCommitted) {
119				t.Fatalf("Read(%d) = %v, want ErrNotCommitted", seq, err)
120			}
121		}
122		if b, err := l.AppendIdempotent("gk", [][]byte{[]byte("k")}); err != nil || b.Seq() != 2 {
123			t.Fatalf("keyed member dedup while staged = %d, %v", b.Seq(), err)
124		}
125		if l.fileSize != 0 {
126			t.Fatalf("segment size after failed group sync = %d, want 0", l.fileSize)
127		}
128	
129		failing = false
130		seqs, err := l.CommitGroup([]Batch{a, k})
131		if err != nil || !reflect.DeepEqual(seqs, []uint64{1, 2}) {
132			t.Fatalf("retry CommitGroup = %v, %v", seqs, err)
133		}
134		var ids []string
135		l.Scan(1, func(b Batch) error { ids = append(ids, b.ID()); return nil })
136		if !reflect.DeepEqual(ids, []string{"", "gk"}) {
137			t.Fatalf("scan ids = %v, want [\"\" gk]", ids)
138		}
139	}
140	
141	func TestKeyedIndexSyncFailureRollsBack(t *testing.T) {
142		dir := t.TempDir()
143		l, err := Open(dir, Options{SegmentBytes: 1 << 20, Sync: true})
144		if err != nil {
145			t.Fatalf("Open: %v", err)
146		}
147		defer l.Close()
148	
149		calls, restore := installFailingSync(t, func(n int) bool { return n == 2 })
150		defer restore()
151	
152		b, err := l.AppendIdempotent("ik", [][]byte{[]byte("r")})
153		if err != nil {
154			t.Fatal(err)
155		}
156		if _, err := l.Commit(b); !errors.Is(err, ErrSyncFailed) {
157			t.Fatalf("Commit err = %v, want ErrSyncFailed", err)
158		}
159		restore()
160		if seq, err := l.Commit(b); err != nil || seq != 1 {
161			t.Fatalf("retry = %d, %v", seq, err)
