func (l *Log) Abort(b Batch) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return errClosed
	}
	recs, ok := l.staged[b.seq]
	if !ok || recs == nil || b.owner != l {
