	// the current segment, is fsynced, then one index sidecar record is
	// appended and fsynced — always, regardless of Options.Sync, so a
	// returned abort survives restarts and index rebuilds.
	marker := encodeHoles([]uint64{b.seq})
	idxBefore := l.idxSize
	off, err := l.writeEntry(marker)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrAbortFailed, err)
	}
	if err := syncFile(l.file); err != nil {
		l.rollbackEntry(off, idxBefore)
		return fmt.Errorf("%w: %v", ErrAbortFailed, err)
	}
	rec := encodeHoleRecord(indexHole{
