// appendAbortRecord appends the hole record to the live sidecar and
// fsyncs it unconditionally: an abort is durable regardless of
// Options.Sync. Failures are wrapped as ErrAbortFailed.
func (l *Log) appendAbortRecord(rec []byte) error {
