	if _, err := l.CommitGroup([]log.Batch{a, c}); err != nil {
		t.Fatalf="CommitGroup without aborted member: %v", err)
	}
	var seqs []uint64
	l.Scan(1, func(b log.Batch) error { seqs = append(seqs, b.Seq()); return nil })
	if !reflect.DeepEqual(seqs, []uint64{1, 3}) {
